import Typography from "@mui/material/Typography";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import Box from "@mui/material/Box";
import IconButton from "@mui/material/IconButton";
import CustomDataGrid from "src/@core/components/data-grid";
import Chip from "@mui/material/Chip";
import { styled } from "@mui/material/styles";
import { MEDIA_URL } from "src/network/endpoints";
import moment from "moment";
import AddIcon from "@mui/icons-material/Add";
import { useState } from "react";
import { useEffect } from "react";
import { Button } from "@mui/material";

function TableClientCategory({
  rows,
  totalCount,
  setCurrentPage,
  currentPage,
  setPageSize,
  pageSize,
  loading,
  toggleEdit,
  toggleDelete,
  toggleAddLogo,
  status,
}) {
  const statusColors = {
    inactive: "#3A3541AD",
    active: "#66bb6a",
  };
  const CustomChip = styled(Chip)(({ label }) => ({
    backgroundColor: statusColors[label] || statusColors.default,
    textTransform: "capitalize",
    color: "#fff",
    width: "100px",
  }));
  const [activeData, setActiveData] = useState([]);
  const [inActiveData, setInActiveData] = useState([]);
  useEffect(() => {
    const activeRows = rows.filter((row) => row.status === "active");
    setActiveData(activeRows);
    const inActiveRows = rows.filter((row) => row.status === "inactive");
    setInActiveData(inActiveRows);
  }, [rows]);
  const displayedRows =
    status === "active"
      ? activeData
      : status === "inactive"
      ? inActiveData
      : rows;
  return (
    <CustomDataGrid
      loading={loading}
      rowCount={totalCount}
      rows={displayedRows}
      columns={[
        {
          field: "category",
          minWidth: 200,
          flex: 1,
          sortable: false,
          headerName: "Category",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.category}>
              {row.category}
            </Typography>
          ),
        },

        {
          field: "created_at",
          minWidth: 230,
          flex: 1,
          sortable: false,
          headerName: "Create Date",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.created_at}>
              {moment(row.created_at).format("DD-MM-YYYY HH:MM")}
            </Typography>
          ),
        },
        {
          field: "updated_at",
          minWidth: 230,
          flex: 1,
          sortable: false,
          headerName: "Updated Date",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.updated_at}>
              {moment(row.updated_at).format("DD-MM-YYYY HH:MM")}
            </Typography>
          ),
        },

        {
          field: "status",
          minWidth: 180,
          flex: 1,
          sortable: false,
          headerName: "Status",
          renderCell: ({ row }) => <CustomChip label={row.status} />,
        },
        {
          field: "Actions",
          flex: 0,
          minWidth: 230,
          sortable: false,
          headerName: "Actions",
          renderCell: ({ row }) => (
            <Box display="flex" alignItems="center" gap="10px">
              <IconButton
                size="small"
                color="primary"
                variant="outlined"
                onClick={(e) => toggleEdit(e, "edit", row)}
              >
                <EditIcon />
              </IconButton>
              <IconButton
                size="small"
                color="secondary"
                onClick={(e) => toggleDelete(e, row)}
              >
                <DeleteIcon />
              </IconButton>
              <Button
                size="small"
                variant="contained"
                onClick={(e) => {
                  toggleAddLogo(e, row.id);
                }}
              >
                Add Logo
              </Button>
            </Box>
          ),
        },
      ]}
      currentPage={currentPage}
      pageSize={pageSize}
      setCurrentPage={setCurrentPage}
      setPageSize={setPageSize}
    />
  );
}

export default TableClientCategory;
